#!/usr/bin/env node

import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const specificationPath = path.join(root, "docs/openapi/management-v1.json");
const outputPath = path.join(root, "web/admin-ui/src/generated/management-client.ts");
const httpMethods = new Set(["get", "post", "patch", "delete"]);

function fail(message) {
  throw new Error(`management-client generator: ${message}`);
}

function resolveReference(specification, reference) {
  if (typeof reference !== "string" || !reference.startsWith("#/")) {
    fail("only local OpenAPI references are supported");
  }
  const value = reference
    .slice(2)
    .split("/")
    .reduce((current, segment) => current?.[segment], specification);
  if (value === undefined || value === null || typeof value !== "object") {
    fail(`unresolved reference ${reference}`);
  }
  return value;
}

function dereference(specification, value) {
  return value?.$ref === undefined ? value : resolveReference(specification, value.$ref);
}

function operationParameters(specification, pathItem, operation) {
  const combined = [...(pathItem.parameters ?? []), ...(operation.parameters ?? [])].map((value) =>
    dereference(specification, value),
  );
  const seen = new Set();
  return combined.map((parameter) => {
    if (
      typeof parameter?.name !== "string" ||
      !["path", "query", "header"].includes(parameter.in)
    ) {
      fail("every operation parameter must have a supported name and location");
    }
    const key = `${parameter.in}:${parameter.name.toLowerCase()}`;
    if (seen.has(key)) {
      fail(`duplicate parameter ${key}`);
    }
    seen.add(key);
    return {
      name: parameter.name,
      in: parameter.in,
      required: parameter.required === true || parameter.in === "path",
    };
  });
}

function requestBodyShape(specification, operation) {
  if (operation.requestBody === undefined) {
    return { bodyEncoding: "none", bodyRequired: false };
  }
  const requestBody = dereference(specification, operation.requestBody);
  const content = requestBody.content ?? {};
  const bodyEncoding = content["application/json"] === undefined
    ? content["application/octet-stream"] === undefined
      ? undefined
      : "binary"
    : "json";
  if (bodyEncoding === undefined) {
    fail(`operation ${operation.operationId} must use a supported request body encoding`);
  }
  return { bodyEncoding, bodyRequired: requestBody.required === true };
}

function collectOperations(specification) {
  if (specification?.openapi !== "3.1.0" || specification?.["x-contract-status"] !== "contract_only") {
    fail("management-v1.json must remain the frozen OpenAPI 3.1 contract-only source");
  }
  const operations = [];
  for (const [route, pathItem] of Object.entries(specification.paths ?? {})) {
    if (!route.startsWith("/admin/")) {
      fail(`non-admin route ${route}`);
    }
    for (const [method, operation] of Object.entries(pathItem)) {
      if (!httpMethods.has(method)) {
        continue;
      }
      if (typeof operation?.operationId !== "string" || !/^[A-Za-z][A-Za-z0-9]*$/.test(operation.operationId)) {
        fail(`invalid operationId at ${method.toUpperCase()} ${route}`);
      }
      const body = requestBodyShape(specification, operation);
      operations.push({
        name: operation.operationId,
        method: method.toUpperCase(),
        path: route,
        parameters: operationParameters(specification, pathItem, operation),
        ...body,
      });
    }
  }
  operations.sort((left, right) => left.name.localeCompare(right.name));
  if (operations.length === 0 || new Set(operations.map((operation) => operation.name)).size !== operations.length) {
    fail("operation IDs must be non-empty and unique");
  }
  return operations;
}

function generatedSource(operations) {
  const wrappers = operations
    .map(
      ({ name }) => `  ${name}(request: ManagementRequest = {}): Promise<Response> {\n    return this.request("${name}", request);\n  }`,
    )
    .join("\n\n");
  operations = Object.fromEntries(
    operations.map(({ name, ...operation }) => [name, operation]),
  );

  return `// This file is generated by scripts/generate-management-client.mjs from docs/openapi/management-v1.json.\n// Do not edit it directly; run npm run generate from web/admin-ui.\n\nexport type ManagementHttpMethod = "GET" | "POST" | "PATCH" | "DELETE";\nexport type ManagementParameterLocation = "path" | "query" | "header";\n\nexport type ManagementParameter = Readonly<{\n  name: string;\n  in: ManagementParameterLocation;\n  required: boolean;\n}>;\n\nexport type ManagementOperation = Readonly<{\n  method: ManagementHttpMethod;\n  path: string;\n  parameters: readonly ManagementParameter[];\n  hasJsonBody: boolean;\n}>;\n\nexport const managementOperations = ${JSON.stringify(operations, null, 2)} as const satisfies Record<string, ManagementOperation>;\n\nexport type ManagementOperationName = keyof typeof managementOperations;\nexport type ManagementScalar = string | number | boolean;\n\nexport type ManagementRequest = Readonly<{\n  path?: Readonly<Record<string, ManagementScalar>>;\n  query?: Readonly<Record<string, ManagementScalar>>;\n  headers?: Readonly<Record<string, ManagementScalar>>;\n  body?: unknown;\n  signal?: AbortSignal;\n}>;\n\nexport type ManagementClientOptions = Readonly<{\n  managementKey: () => string | undefined;\n  csrfToken?: () => string | undefined;\n  fetch?: typeof fetch;\n}>;\n\nconst managementKeyHeader = "X-Management-Key";\nconst csrfHeader = "X-Management-CSRF-Token";\n\nfunction inputFor(\n  values: Readonly<Record<string, ManagementScalar>> | undefined,\n  parameter: ManagementParameter,\n): ManagementScalar | undefined {\n  if (values === undefined) {\n    return undefined;\n  }\n  if (parameter.in !== "header") {\n    return values[parameter.name];\n  }\n  const matched = Object.entries(values).find(([name]) => name.toLowerCase() === parameter.name.toLowerCase());\n  return matched?.[1];\n}\n\nfunction ensureOnlyDeclared(\n  values: Readonly<Record<string, ManagementScalar>> | undefined,\n  operation: ManagementOperation,\n  location: ManagementParameterLocation,\n): void {\n  if (values === undefined) {\n    return;\n  }\n  const declared = operation.parameters.filter((parameter) => parameter.in === location);\n  for (const name of Object.keys(values)) {\n    const known = declared.some((parameter) =>\n      location === "header"\n        ? parameter.name.toLowerCase() === name.toLowerCase()\n        : parameter.name === name,\n    );\n    if (!known) {\n      throw new Error(\`undeclared management \${location} input\`);\n    }\n  }\n}\n\nfunction relativeOperationPath(operation: ManagementOperation, request: ManagementRequest): string {\n  ensureOnlyDeclared(request.path, operation, "path");\n  ensureOnlyDeclared(request.query, operation, "query");\n  let pathname = operation.path.replace(/\\{([^}]+)\\}/gu, (_match, parameterName: string) => {\n    const parameter = operation.parameters.find(\n      (candidate) => candidate.in === "path" && candidate.name === parameterName,\n    );\n    const value = parameter === undefined ? undefined : inputFor(request.path, parameter);\n    if (value === undefined || String(value).length === 0) {\n      throw new Error("missing required management path input");\n    }\n    return encodeURIComponent(String(value));\n  });\n\n  const query = new URLSearchParams();\n  for (const parameter of operation.parameters.filter((candidate) => candidate.in === "query")) {\n    const value = inputFor(request.query, parameter);\n    if (value === undefined) {\n      if (parameter.required) {\n        throw new Error("missing required management query input");\n      }\n      continue;\n    }\n    query.set(parameter.name, String(value));\n  }\n  const search = query.toString();\n  return search.length === 0 ? pathname : \`\${pathname}?\${search}\`;\n}\n\nfunction configuredSecret(value: string | undefined, headerName: string): string {\n  if (value === undefined || value.length === 0) {\n    throw new Error(\`\${headerName} is not configured\`);\n  }\n  return value;\n}\n\nexport class ManagementApi {\n  readonly #managementKey: () => string | undefined;\n  readonly #csrfToken: (() => string | undefined) | undefined;\n  readonly #fetch: typeof fetch;\n\n  constructor(options: ManagementClientOptions) {\n    this.#managementKey = options.managementKey;\n    this.#csrfToken = options.csrfToken;\n    this.#fetch = options.fetch ?? fetch;\n  }\n\n  async request(\n    operationName: ManagementOperationName,\n    request: ManagementRequest = {},\n  ): Promise<Response> {\n    const operation = managementOperations[operationName];\n    ensureOnlyDeclared(request.headers, operation, "header");\n    if (request.headers?.[managementKeyHeader] !== undefined || request.headers?.[csrfHeader] !== undefined) {\n      throw new Error("management authentication headers are configured only by client options");\n    }\n\n    const headers = new Headers({ Accept: "application/json" });\n    headers.set(managementKeyHeader, configuredSecret(this.#managementKey(), managementKeyHeader));\n    for (const parameter of operation.parameters.filter((candidate) => candidate.in === "header")) {\n      const value = inputFor(request.headers, parameter);\n      if (value === undefined) {\n        if (parameter.required) {\n          throw new Error("missing required management header input");\n        }\n        continue;\n      }\n      headers.set(parameter.name, String(value));\n    }\n\n    const unsafe = operation.method !== "GET";\n    if (unsafe) {\n      headers.set(csrfHeader, configuredSecret(this.#csrfToken?.(), csrfHeader));\n    }\n\n    let body: string | undefined;\n    if (operation.hasJsonBody) {\n      if (request.body === undefined) {\n        throw new Error("missing required management JSON body");\n      }\n      body = JSON.stringify(request.body);\n      if (body === undefined) {\n        throw new Error("management JSON body is not serializable");\n      }\n      headers.set("Content-Type", "application/json");\n    } else if (request.body !== undefined) {\n      throw new Error("management operation does not accept a body");\n    }\n\n    return this.#fetch(relativeOperationPath(operation, request), {\n      method: operation.method,\n      headers,\n      body,\n      signal: request.signal,\n      credentials: "same-origin",\n      redirect: "error",\n    });\n  }\n\n${wrappers}\n}\n`;
}

const checkOnly = process.argv.slice(2).join(" ") === "--check";
if (!checkOnly && process.argv.length !== 2) {
  fail("usage: generate-management-client.mjs [--check]");
}

const specification = JSON.parse(await readFile(specificationPath, "utf8"));
let source = generatedSource(collectOperations(specification));
source = source
  .replace(
    "  hasJsonBody: boolean;\n}>;",
    "  bodyEncoding: \"none\" | \"json\" | \"binary\";\n  bodyRequired: boolean;\n}>;",
  )
  .replace(
    `    let body: string | undefined;
    if (operation.hasJsonBody) {
      if (request.body === undefined) {
        throw new Error("missing required management JSON body");
      }
      body = JSON.stringify(request.body);
      if (body === undefined) {
        throw new Error("management JSON body is not serializable");
      }
      headers.set("Content-Type", "application/json");
    } else if (request.body !== undefined) {`,
    `    let body: BodyInit | undefined;
    if (operation.bodyEncoding === "json") {
      if (request.body === undefined && operation.bodyRequired) {
        throw new Error("missing required management JSON body");
      }
      if (request.body !== undefined) {
        body = JSON.stringify(request.body);
        if (body === undefined) {
          throw new Error("management JSON body is not serializable");
        }
        headers.set("Content-Type", "application/json");
      }
    } else if (operation.bodyEncoding === "binary") {
      if (request.body === undefined && operation.bodyRequired) {
        throw new Error("missing required management binary body");
      }
      if (request.body !== undefined) {
        body = request.body as BodyInit;
        headers.set("Content-Type", "application/octet-stream");
      }
    } else if (request.body !== undefined) {`,
  );
source = source.replace(
  "this.#fetch = options.fetch ?? fetch;",
  "this.#fetch = options.fetch ?? globalThis.fetch.bind(globalThis);",
);
if (checkOnly) {
  const existing = await readFile(outputPath, "utf8").catch(() => "");
  if (existing !== source) {
    fail("generated client is stale; run npm run generate from web/admin-ui");
  }
} else {
  await writeFile(outputPath, source, "utf8");
}
